import fs from 'node:fs';
import path from 'node:path';
import {spawn} from 'node:child_process';
const [label,deadlineText,command,...args]=process.argv.slice(2);
const group=fs.readFileSync('/proc/self/cgroup','utf8').trim().split('\n').find(x=>x.startsWith('0::')).slice(3);
const cg='/sys/fs/cgroup'+group;
const read=name=>fs.readFileSync(cg+'/'+name,'utf8').trim();
const start=performance.now();
const record={label,command:[command,...args],group,memoryMax:read('memory.max'),memorySwapMax:read('memory.swap.max'),startedAt:new Date().toISOString(),samples:0};
if(record.memoryMax!=='8589934592'||record.memorySwapMax!=='0')throw Error('Real cgroup limits mismatch');
const save=()=>{Object.assign(record,{elapsedMs:performance.now()-start,memoryPeak:read('memory.peak'),memoryCurrent:read('memory.current'),memoryEvents:read('memory.events'),cpuStat:read('cpu.stat')});record.samples++;fs.writeFileSync(label+'.guard.json',JSON.stringify(record,null,2)+'\n');};
save();
const out=fs.openSync(label+'.stdout.log','wx'),err=fs.openSync(label+'.stderr.log','wx');
const child=spawn(command,args,{stdio:['ignore',out,err],detached:true});
record.pid=child.pid;
const tick=setInterval(save,250);
const timer=setTimeout(()=>{record.internalDeadline=true;try{process.kill(-child.pid,'SIGKILL');}catch{}},Number(deadlineText));
child.on('error',error=>{record.spawnError=String(error);});
child.on('close',(code,signal)=>{clearInterval(tick);clearTimeout(timer);record.exitCode=code;record.signal=signal;save();fs.closeSync(out);fs.closeSync(err);process.exitCode=code===0?0:1;});

