import fs from 'node:fs';
import {spawnSync} from 'node:child_process';
const [label,seconds,command,...args]=process.argv.slice(2);
const unit='bend-native46-elcWbhvH-'+label;
const argv=['--user','--scope','--quiet','--unit='+unit,'-p','MemoryMax=8589934592','-p','MemorySwapMax=0','-p','RuntimeMaxSec='+seconds+'s','/usr/bin/node','guard.mjs',label,String((Number(seconds)-10)*1000),command,...args];
const before=Date.now();
const r=spawnSync('systemd-run',argv,{encoding:'utf8',timeout:(Number(seconds)+20)*1000,maxBuffer:1024*1024});
const show=spawnSync('systemctl',['--user','show',unit+'.scope','-p','Result','-p','ActiveState','-p','SubState','-p','ControlGroup','-p','MemoryMax','-p','MemorySwapMax','-p','RuntimeMaxUSec'],{encoding:'utf8'});
const receipt={command:['systemd-run',...argv],elapsedMs:Date.now()-before,status:r.status,signal:r.signal,error:r.error?String(r.error):null,stdout:r.stdout,stderr:r.stderr,systemctlShow:{status:show.status,stdout:show.stdout,stderr:show.stderr}};
if(r.status!==0){const kill=spawnSync('systemctl',['--user','kill','--kill-whom=all','--signal=SIGKILL',unit+'.scope'],{encoding:'utf8'});receipt.cleanupKill={status:kill.status,stdout:kill.stdout,stderr:kill.stderr};}
fs.writeFileSync(label+'.systemd.json',JSON.stringify(receipt,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify(receipt));process.exitCode=r.status===0?0:1;

